(()=>{let t=self;t.addEventListener("notificationclick",i=>{i.notification.close();let e=i.notification.data?.url||"/";i.waitUntil(t.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let t of i)if("focus"in t){t.focus(),t.postMessage({type:"NOTIFICATION_CLICK",url:e});return}return t.clients.openWindow(e)}))}),t.addEventListener("push",i=>{try{let e={};if(i.data)try{e=i.data.json()}catch{e={body:i.data.text()}}let o=e.title||"Obel",n={icon:"/obel.png",badge:"/obel.png",vibrate:[200,100,200],...e,data:{url:e.data?.url||e.url||"/"}};i.waitUntil(t.registration.showNotification(o,n))}catch(e){console.error("[ServiceWorker] Push event error:",e),i.waitUntil(t.registration.showNotification("Obel Notification",{body:"A notification is waiting for you",icon:"/obel.png"}))}})})();